FROM notifications
WHERE recipient_id = #{recipientId}

    AND is_read = #{isRead}

ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT count(*)
FROM notifications
WHERE recipient_id = #{recipientId}

    AND is_read = #{isRead}

SELECT id, recipient_id, type, work_item_id, message, is_read, created_at
FROM notifications
WHERE id = #{id}

mapper.update:
UPDATE notifications
SET is_read = true
WHERE id = #{id} AND recipient_id = #{recipientId}

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM notifications
    WHERE recipient_id = #{recipientId}
      AND work_item_id = #{workItemId}
      AND type = #{type}
      AND created_at >= date_trunc('day', now())
)
